/* compare_by_identity bucket: the address (moves with the GC, which drops the index) */
static inline uint64_t korb_id_hash(korb_value v) { uint64_t x = (uint64_t)v; x ^= x >> 33; x *= 0xff51afd7ed558ccdULL; x ^= x >> 29; return x; }
