#undef KORB_SDI_E
uint8_t
korb_sdi_kind(const struct korb_vm *vm, uint32_t mid, uint32_t argc)
{
    const char *const nm = korb_sym_name((struct korb_vm *)(uintptr_t)vm, mid);
    for (uint8_t k = 1; k < KORB_SDI_N; k++)
        if (argc == korb_sdi_tab[k].argc && strcmp(nm, korb_sdi_tab[k].name) == 0) return k;
    return KORB_SDI_NONE;
}
const char *
korb_sdi_eval_name(const struct Node *n, const char *base)
{
    const uint8_t k = n->head.flags.sd_inl;
    return k != KORB_SDI_NONE && k < KORB_SDI_N ? korb_sdi_tab[k].eval : base;
}
/* stands in a korb_sdi_tab row whose builtins were not found: no method has this rfn */
_Static_assert(KORB_SDI_N <= 64, "KorbClass.sdi_ok is one 64-bit mask");
/* Does `kl` resolve inline send `k` to one of its builtins (public)?  Answered once per class and
 * method_serial into kl's masks; the AOT inline send asks when its site's cache holds another class
 * (liquid's `object.respond_to?(:[])` sees Hash / String / Drop at one site). */
static bool korb_sdi_class_resolve(CTX *c, korb_value kl, unsigned k);
/* The AOT inline send's miss side (its site cache holds another class): kl's own per-kind answer.
 * Out of line and cold, so the hit path keeps the shape it had before the masks (nil_p +4.6%
 * instructions with this inlined). */
/* korb_sdi_klass for all but a plain instance: one shared copy for the SDs built with KORB_SD_SHARE_KL */
__attribute__((noinline)) korb_value
korb_sdi_klass_slow(const struct korb_vm *vm, const korb_value r)
{
    if (AROH_IS_GC_OBJECT(r)) {
        const uint16_t f = ((const AroObjectHeader *)(uintptr_t)r)->flags & (KORB_OBJ_TYPE_MASK | KORB_FL_HAS_KLASS);
        if (f == KORB_OBJ_OBJECT) return VAL2OBJ(r)->klass;
        if (f == KORB_OBJ_STRING) return korb_builtin_class_obj(vm, KORB_C_STRING);
        if (f == KORB_OBJ_ARRAY) return korb_builtin_class_obj(vm, KORB_C_ARRAY);
        if (f == KORB_OBJ_HASH) return korb_builtin_class_obj(vm, KORB_C_HASH);
        if (f == KORB_OBJ_REGEXP) return korb_builtin_class_obj(vm, KORB_C_REGEXP);
        return KORB_NIL;
    }
    if (FIXNUM_P(r)) return korb_builtin_class_obj(vm, KORB_C_INTEGER);
    if (FLONUM_P(r)) return korb_builtin_class_obj(vm, KORB_C_FLOAT);
    if (r == KORB_NIL) return korb_builtin_class_obj(vm, KORB_C_NIL);
    if (r == KORB_TRUE) return korb_builtin_class_obj(vm, KORB_C_TRUE);
    if (r == KORB_FALSE) return korb_builtin_class_obj(vm, KORB_C_FALSE);
    return KORB_NIL;
}
__attribute__((noinline, cold)) bool
korb_sdi_class_ok(CTX *c, korb_value kl, unsigned k)
{
    if (UNLIKELY(c->vm->refinements_active) && c->refinements != KORB_NIL) return false;
    const KorbClass *const kc = VAL2CLASS(kl);
    if (LIKELY(kc->sdi_serial == c->vm->method_serial && ((kc->sdi_known >> k) & 1u)))
        return (kc->sdi_ok >> k) & 1u;
    return korb_sdi_class_resolve(c, kl, k);
}
static bool
korb_sdi_class_resolve(CTX *c, korb_value kl, unsigned k)
{
    struct korb_vm *const vm = c->vm;
    KorbClass *const kc = VAL2CLASS(kl);
    if (kc->sdi_serial != vm->method_serial) { kc->sdi_ok = kc->sdi_known = 0; kc->sdi_serial = vm->method_serial; }
    korb_value def = KORB_NIL;
    const struct korb_method *const m = korb_mcache_find(vm, kl, vm->sdi_mid[k], &def);
    bool ok = false;
    if (m != NULL && m->kind == KORB_METHOD_CFUNC && !m->uses_block && m->visibility == 0)
        for (int j = 0; j < KORB_SDI_FN_MAX; j++) if (m->rfn == vm->sdi_fn[k][j]) { ok = true; break; }
    kc->sdi_known |= 1ull << k;
    if (ok) kc->sdi_ok |= 1ull << k;
    return ok;
}
static RESULT korb_sdi_never(CTX *c, korb_value *slots, korb_ref self, korb_slice a) { (void)self; (void)a; return korb_raise(c, slots, KORB_E_RUNTIME, 0, "korb_sdi_never"); }
/* Until korb_sdi_init (after the prelude), no inline send stands for anything.  A zeroed
 * table matched every Ruby method (NULL rfn): the AOT-compiled prelude then took
 * KORB_SDI_DIRECT into a NULL call for a name the prelude defines in Ruby (String#encoding). */
void
korb_sdi_preinit(struct korb_vm *vm)
{
    for (unsigned k = 0; k < KORB_SDI_N; k++)
        for (int j = 0; j < KORB_SDI_FN_MAX; j++) vm->sdi_fn[k][j] = korb_sdi_never;
}
static const enum korb_class korb_s2s_cls[6] = { KORB_C_INTEGER, KORB_C_FLOAT, KORB_C_SYMBOL, KORB_C_NIL, KORB_C_TRUE, KORB_C_FALSE };
/* Are the scalars' #to_s all still the booted C functions?  Looking the name up marks
 * it, so a later redefinition moves method_serial and brings us back here. */
static bool
korb_scalar_to_s_check(struct korb_vm *vm)
{
    const uint32_t mid = korb_intern_lit(vm, "to_s", 4);
    bool ok = vm->boot_done;
    for (int i = 0; i < 6 && ok; i++) {
        korb_value d = KORB_NIL;
        const struct korb_method *const m = korb_class_find_method(korb_builtin_class_obj(vm, korb_s2s_cls[i]), mid, &d);
        ok = vm->s2s_fn[i] != NULL && m != NULL && m->kind == KORB_METHOD_CFUNC && m->rfn == vm->s2s_fn[i];
    }
    korb_mid_looked(vm, mid);
    vm->s2s_serial = vm->method_serial;
    vm->s2s_ok = ok;
    return ok;
}
void
korb_sdi_init(CTX *c)
{
    struct korb_vm *const vm = c->vm;
    for (uint8_t k = 1; k < KORB_SDI_N; k++) {
        const uint32_t mid = korb_intern(vm, korb_sdi_tab[k].name, strlen(korb_sdi_tab[k].name));
        vm->sdi_mid[k] = mid;
        for (int j = 0; j < KORB_SDI_FN_MAX && korb_sdi_tab[k].cls[j] >= 0; j++) {
            korb_value def = KORB_NIL;
            const struct korb_method *const m = korb_class_find_method(korb_builtin_class_obj(vm, (enum korb_class)korb_sdi_tab[k].cls[j]), mid, &def);
            vm->sdi_fn[k][j] = (m != NULL && m->kind == KORB_METHOD_CFUNC && !m->uses_block) ? m->rfn : NULL;
            if (vm->sdi_fn[k][j] != NULL) ((struct korb_method *)(uintptr_t)m)->sdi_k = k;   /* KORB_SDI_HIT's one compare */
        }
        /* an unused cell repeats a real one: a NULL there would match a Ruby method's
         * (NULL) rfn in KORB_SDI_HIT and call it.  All NULL = never matched (korb_sdi_never). */
        korb_method_fn first = NULL;
        for (int j = 0; j < KORB_SDI_FN_MAX && first == NULL; j++) first = vm->sdi_fn[k][j];
        for (int j = 0; j < KORB_SDI_FN_MAX; j++) if (vm->sdi_fn[k][j] == NULL) vm->sdi_fn[k][j] = first ? first : korb_sdi_never;
    }
    korb_value d = KORB_NIL;
    vm->rtm_default = korb_find_method_c(vm, korb_const_get(vm, korb_intern_lit(vm, "Kernel", 6)), vm->mid_respond_to_missing, &d);
    for (int i = 0; i < 6; i++) {
        const struct korb_method *const m = korb_class_find_method(korb_builtin_class_obj(vm, korb_s2s_cls[i]), korb_intern_lit(vm, "to_s", 4), &d);
        vm->s2s_fn[i] = (m != NULL && m->kind == KORB_METHOD_CFUNC) ? m->rfn : NULL;
    }
    vm->method_serial++;   /* a class mask answered during the prelude saw the empty table */
}

/* ---- integer formatting (to_s / chr helpers) ----------------------------- */

static uint32_t
korb_fmt_int(korb_sword_t n, int base, char *buf)
{
    char tmp[80];
    int ti = 0;
    bool neg = n < 0;
    uintptr_t u = neg ? (uintptr_t)(-(n + 1)) + 1u : (uintptr_t)n;
    if (u == 0) tmp[ti++] = '0';
    while (u) { int d = (int)(u % (uintptr_t)base); tmp[ti++] = d < 10 ? (char)('0'+d) : (char)('a'+d-10); u /= (uintptr_t)base; }
    uint32_t len = 0;
    if (neg) buf[len++] = '-';
    while (ti) buf[len++] = tmp[--ti];
    return len;
}

